import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
reach = [[False] * n for _ in range(n)]
for k in range(m):
    a, b = int(data[2 + 2 * k]), int(data[3 + 2 * k])
    reach[b][a] = True
for w in range(n):
    for i in range(n):
        if reach[i][w]:
            for j in range(n):
                if reach[w][j]:
                    reach[i][j] = True
print('false' if any(reach[i][i] for i in range(n)) else 'true')

